problems.reference_solution:
n = int(input())
for width in range(1, n + 1):
    print("*" * width)

digits = [int(character) for character in input() if character != " "]
total = 0
for index, digit in enumerate(reversed(digits)):
    if index % 2 == 1:
        digit *= 2
        if digit > 9:
            digit -= 9
    total += digit
print("YES" if total % 10 == 0 else "NO")

digits = [int(character) for character in input().strip()]
k = int(input())
if k == 0:
    print(1)
else:
    best = 0
    for start in range(len(digits) - k + 1):
        product = 1
        for digit in digits[start:start + k]:
            product *= digit
        best = max(best, product)
    print(best)

rows, columns = map(int, input().split())
grid = [input().strip() for _ in range(rows)]
result = []
for row in range(rows):
    output_row = []
    for column in range(columns):
        if grid[row][column] == "*":
            output_row.append("*")
            continue
        count = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = row + dr, column + dc
                if 0 <= nr < rows and 0 <= nc < columns and grid[nr][nc] == "*":
                    count += 1
        output_row.append(str(count))
    result.append("".join(output_row))
print("\n".join(result))

rows, columns = map(int, input().split())
matrix = [list(map(int, input().split())) for _ in range(rows)]
points = []
for row in range(rows):
    row_max = max(matrix[row])
    for column in range(columns):
        value = matrix[row][column]
        if value == row_max and value == min(matrix[index][column] for index in range(rows)):
            points.append((row + 1, column + 1))
if points:
    print("\n".join(f"{row} {column}" for row, column in points))
else:
    print("NONE")

text = input().strip()
stack = []
pairs = {")": "(", "]": "[", "}": "{"}
valid = True
for character in text:
    if character in "([{":
        stack.append(character)
    elif not stack or stack.pop() != pairs[character]:
        valid = False
        break
print("YES" if valid and not stack else "NO")
